<template>
  <div>
    <v-layout class="section darken" row wrap>
      <v-flex lg12 md12 xs12 sm12>
        <h2
          class="mywhiteText display-2 text-lg-center text-md-center mt-5 text-xs-center"
        >CONTACT US</h2>
        <div class="form">
          <v-form v-model="valid">
            <v-layout row wrap>
              <v-text-field
                dark
                background-color="transparent"
                color="green"
                box="true"
                v-model="firstname"
                :rules="nameRules"
                :counter="10"
                label="Name"
                class="my-input"
                required
              ></v-text-field>
            </v-layout>

            <v-layout row wrap>
              <v-text-field
                dark
                color="green"
                background-color="transparent"
                v-model="email"
                :rules="emailRules"
                :counter="50"
                box="true"
                label="E-mail"
                class="my-input"
                required
              ></v-text-field>
            </v-layout>

            <v-layout row wrap>
              <v-text-field
                height="6em"
                dark
                color="green"
                box="true"
                background-color="transparent"
                v-model="message"
                label="Message"
                class="my-input"
                required
              ></v-text-field>
            </v-layout>

            <v-layout row wrap>
              <v-btn
                large
                flat
                :disabled="!valid"
                color="#2CC804"
                @click="validate"
                class="myBtn"
              >Send</v-btn>
            </v-layout>
          </v-form>
        </div>
      </v-flex>
      <v-flex lg12 md12 xs12 sm12>
        <v-layout class="socialIcons" justify-space-around>
          <v-icon color="white">fab fa-facebook</v-icon>
          <v-icon color="white">fab fa-youtube</v-icon>
          <v-icon color="white">fab fa-twitter</v-icon>
          <v-icon color="white">fab fa-whatsapp</v-icon>
        </v-layout>
      </v-flex>
      <v-flex lg12 md12 xs12 sm12>
        <v-layout class="copyText" justify-space-around>
          <p>&copy; 2019 Fort Hotel</p>
        </v-layout>
      </v-flex>
    </v-layout>
  </div>
</template>
<script>
export default {
  name: "AppFooter",
  data() {
    return {
      valid: false,
      name: "",
      lastname: "",
      nameRules: [
        v => !!v || "Name is required",
        v => v.length <= 10 || "Name must be less than 10 characters"
      ],
      email: "",
      emailRules: [
        v => !!v || "E-mail is required",
        v => /.+@.+/.test(v) || "E-mail must be valid"
      ]
    };
  }
};
</script>
<style scoped>
@import "../assets/css/style.css";

.form,
.socialIcons,
.copyText {
  width: 30vw;
  margin: 1em auto;
}

.copyText {
  margin-top: 1em;
  color: white;
}

.my-input.v-input .v-input__slot {
  border-radius: 0px;
}

@media screen and (max-width: 500px) {
  .form {
    width: 80vw;
    margin: 1em auto;
  }
}
</style>
